INSERT INTO "strategies" ("id", "slug", "name", "description", "kind", "status", "source_ref", "tags", "section", "params") VALUES
  ('strategy-seed-qc-iv-rank-gate', 'qc-iv-rank-gate', 'IV-Rank Gate for Credit Spreads', 'Reusable gate: sell defined-risk put credit verticals only when the IV rank of the symbol''s CBOE vol index (252 days) is at least 50. Measured as a before/after effect on existing strategies. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-iv-rank-gate.', 'python', 'researching', 'docs/specs/strategies/qc-iv-rank-gate.md', '["research-only","quantconnect-idea","options","defined-risk","gate"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-turn-of-the-month', 'qc-turn-of-the-month', 'Turn of the Month (option verticals)', 'Call debit vertical on SPY, QQQ, DIA, IWM held from trading day -2 to +3 around month end. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-turn-of-the-month.', 'python', 'researching', 'docs/specs/strategies/qc-turn-of-the-month.md', '["research-only","quantconnect-idea","options","defined-risk","calendar"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-opex-week', 'qc-opex-week', 'Option-Expiration Week Effect', 'Call debit vertical held during the monthly option-expiration week on the equity ETF twins. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-opex-week.', 'python', 'researching', 'docs/specs/strategies/qc-opex-week.md', '["research-only","quantconnect-idea","options","defined-risk","calendar"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-regime-put-vrp', 'qc-regime-put-vrp', 'Regime-Gated Put VRP', '25-delta put credit verticals (~45 DTE, 50% profit take, close at 21 DTE) only in calm, uptrend regimes: VIX <= 25, VIX/VIX3M <= 1, SPY above its 200-day SMA. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-regime-put-vrp.', 'python', 'researching', 'docs/specs/strategies/qc-regime-put-vrp.md', '["research-only","quantconnect-idea","options","defined-risk","vrp"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-futures-trend-carry', 'qc-futures-trend-carry', 'Futures Trend + Carry on Core 7', 'Signal from the Core 7 futures 12-month trend strength and a carry proxy; expressed as debit verticals on the ETF twins. No naked futures. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-futures-trend-carry.', 'python', 'researching', 'docs/specs/strategies/qc-futures-trend-carry.md', '["research-only","quantconnect-idea","options","defined-risk","trend"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-vix-term-gate', 'qc-vix-term-gate', 'VIX Term-Structure Gate', 'Reusable gate: bullish entries only in contango (VIX/VIX3M < 1); includes the VIX-predicts-index-returns quintile table. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-vix-term-gate.', 'python', 'researching', 'docs/specs/strategies/qc-vix-term-gate.md', '["research-only","quantconnect-idea","options","defined-risk","gate"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-asset-class-trend', 'qc-asset-class-trend', 'Asset-Class Trend (10-month SMA)', 'Monthly: call debit vertical (~60 DTE) on each Core 7 ETF twin above its 10-month SMA; flat otherwise. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-asset-class-trend.', 'python', 'researching', 'docs/specs/strategies/qc-asset-class-trend.md', '["research-only","quantconnect-idea","options","defined-risk","trend"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-momentum-rotation', 'qc-momentum-rotation', 'Asset-Class Momentum Rotation', 'Monthly: call debit verticals on the top 2 Core 7 ETF twins by 12-1 month momentum, only when momentum is positive. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-momentum-rotation.', 'python', 'researching', 'docs/specs/strategies/qc-momentum-rotation.md', '["research-only","quantconnect-idea","options","defined-risk","momentum"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-gold-fed-model', 'qc-gold-fed-model', 'Gold Market Timing (Fed model)', 'Monthly: GLD call debit vertical when the S&P earnings yield (Shiller, lagged 3 months) is above 2x the 10-year yield. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-gold-fed-model.', 'python', 'researching', 'docs/specs/strategies/qc-gold-fed-model.md', '["research-only","quantconnect-idea","options","defined-risk","macro"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-oil-predicts-equity', 'qc-oil-predicts-equity', 'Crude Oil Predicts Equity Returns', 'Monthly rolling regression of next-month SPY excess return on last-month USO return; call debit verticals on SPY/QQQ when the forecast beats T-bills. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-oil-predicts-equity.', 'python', 'researching', 'docs/specs/strategies/qc-oil-predicts-equity.md', '["research-only","quantconnect-idea","options","defined-risk","macro"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb),
  ('strategy-seed-qc-same-month-seasonality', 'qc-same-month-seasonality', 'Same-Calendar-Month Seasonality', 'Monthly: call debit verticals on the top 2 Core 7 twins by average same-calendar-month return over prior years, when positive. Research only (no orders). Option prices MODELED with Black-Scholes on CBOE vol-index proxies; 2% max-loss sizing; Nautilus backtest results in research_studies id qc-same-month-seasonality.', 'python', 'researching', 'docs/specs/strategies/qc-same-month-seasonality.md', '["research-only","quantconnect-idea","options","defined-risk","seasonality"]'::jsonb, 'QuantConnect ideas', '[]'::jsonb)
